			radiant.position.set(0, .2 + (h - .28) / 2, -d / 3);
			group.add(radiant);
			const spit = new Mesh(new CylinderGeometry(.015, .015, h - .2), mats.stainless);
			spit.position.set(0, h / 2, .05);
